SELECT "t8"."order_number", "t8"."line_no", "t8"."item", "t8"."unit_price", "t8"."list_price", 'hold_sales' AS "route", 'price_differences' AS "context"
FROM (SELECT "order_number0" AS "order_number", "line_no0" AS "line_no", "item", "unit_price", "price" AS "list_price"
        FROM (SELECT "t1"."order_number", "t1"."line_no", "t1"."item", "t1"."unit_price", "t1"."customer", "t1"."channel", "t1"."placed_date", "t5"."order_number" AS "order_number0", "t5"."line_no" AS "line_no0", "t5"."price"
                FROM (SELECT "sales_line"."order_number", "sales_line"."line_no", "sales_line"."item", "sales_line"."unit_price", "t0"."customer", "t0"."channel", "t0"."placed_date"
                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                FROM "order"
                                WHERE "state" IN ('held', 'placed')) AS "t0"
                            INNER JOIN "sales_line" ON "t0"."order_number" = "sales_line"."order_number") AS "t1"
                    INNER JOIN (SELECT "t4"."order_number", "t4"."line_no", COALESCE("customer_price"."price", "price_list"."price") AS "price"
                        FROM (SELECT "sales_line0"."order_number", "sales_line0"."line_no", "sales_line0"."item", "sales_line0"."unit_price", "t3"."customer", "t3"."channel", "t3"."placed_date"
                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                        FROM "order"
                                        WHERE "state" IN ('held', 'placed')) AS "t3"
                                    INNER JOIN "sales_line" AS "sales_line0" ON "t3"."order_number" = "sales_line0"."order_number") AS "t4"
                            LEFT JOIN "customer_price" ON "t4"."item" = "customer_price"."item" AND "t4"."customer" = "customer_price"."customer" AND "t4"."placed_date" >= "customer_price"."valid_from" AND ("customer_price"."valid_to" IS NULL OR "t4"."placed_date" <= "customer_price"."valid_to")
                            LEFT JOIN "price_list" ON "t4"."item" = "price_list"."item" AND "t4"."channel" = "price_list"."channel" AND "t4"."placed_date" >= "price_list"."valid_from" AND ("price_list"."valid_to" IS NULL OR "t4"."placed_date" <= "price_list"."valid_to")) AS "t5" ON "t1"."order_number" = "t5"."order_number" AND "t1"."line_no" = "t5"."line_no") AS "t6"
        WHERE "t6"."price" IS NULL OR ABS("t6"."unit_price" - "t6"."price") > :tolerance) AS "t8"
    INNER JOIN (SELECT "order_number"
        FROM (SELECT "t38"."order_number", "t38"."customer", "t38"."channel", "t38"."fulfilling_warehouse", "t38"."value", "t38"."placed_date", "t38"."state", COALESCE("t38"."n_short", 0) AS "n_short", COALESCE("t38"."n_price", 0) AS "n_price", COALESCE("t44"."n_due", 0) AS "n_due"
                FROM (SELECT "t26"."order_number", "t26"."customer", "t26"."channel", "t26"."fulfilling_warehouse", "t26"."value", "t26"."placed_date", "t26"."state", "t26"."n_short", "t37"."n_price"
                        FROM (SELECT "t10"."order_number", "t10"."customer", "t10"."channel", "t10"."fulfilling_warehouse", "t10"."value", "t10"."placed_date", "t10"."state", "t25"."n_short"
                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                        FROM "order"
                                        WHERE "state" IN ('held', 'placed')) AS "t10"
                                    LEFT JOIN (SELECT "order_number", COUNT("line_no") AS "n_short"
                                        FROM (SELECT "t20"."order_number", "t20"."customer", "t20"."channel", "t20"."fulfilling_warehouse", "t20"."value", "t20"."placed_date", "t20"."state", "t20"."line_no", "t20"."item", "t20"."quantity", "t20"."unit_price", "t20"."ext_sales_price", "t20"."warehouse", "t20"."sold_date", "t20"."customer0", "t20"."channel0", "t20"."as_of_date", "t20"."quantity_on_hand", "t20"."_ttrp_g_n9_0", "t20"."_ttrp_g_n9_1", "t21"."warehouse" AS "warehouse0", "t21"."from_date", "t21"."to_date", "t21"."reason", COALESCE("t20"."quantity_on_hand", 0) AS "on_hand", "t21"."warehouse" IS NOT NULL AS "outage"
                                                FROM (SELECT "t14"."order_number", "t14"."customer", "t14"."channel", "t14"."fulfilling_warehouse", "t14"."value", "t14"."placed_date", "t14"."state", "t14"."line_no", "t14"."item", "t14"."quantity", "t14"."unit_price", "t14"."ext_sales_price", "t14"."warehouse", "t14"."sold_date", "t14"."customer0", "t14"."channel0", "t14"."as_of_date", "t14"."quantity_on_hand", "t14"."_ttrp_g_n9_0", "t14"."_ttrp_g_n9_1"
                                                        FROM (SELECT "t13"."order_number", "t13"."customer", "t13"."channel", "t13"."fulfilling_warehouse", "t13"."value", "t13"."placed_date", "t13"."state", "t13"."line_no", "t13"."item", "t13"."quantity", "t13"."unit_price", "t13"."ext_sales_price", "t13"."warehouse", "t13"."sold_date", "t13"."customer0", "t13"."channel0", "inventory"."as_of_date", "inventory"."quantity_on_hand", CASE WHEN "t13"."order_number" IS NULL THEN 'n' ELSE 'v' || CAST("t13"."order_number" AS VARCHAR) END AS "_ttrp_g_n9_0", CASE WHEN "t13"."line_no" IS NULL THEN 'n' ELSE 'v' || CAST("t13"."line_no" AS VARCHAR) END AS "_ttrp_g_n9_1"
                                                                FROM (SELECT "t12"."order_number", "t12"."customer", "t12"."channel", "t12"."fulfilling_warehouse", "t12"."value", "t12"."placed_date", "t12"."state", "sales_line1"."line_no", "sales_line1"."item", "sales_line1"."quantity", "sales_line1"."unit_price", "sales_line1"."ext_sales_price", "sales_line1"."warehouse", "sales_line1"."sold_date", "sales_line1"."customer" AS "customer0", "sales_line1"."channel" AS "channel0"
                                                                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                                FROM "order"
                                                                                WHERE "state" IN ('held', 'placed')) AS "t12"
                                                                            INNER JOIN "sales_line" AS "sales_line1" ON "t12"."order_number" = "sales_line1"."order_number") AS "t13"
                                                                    LEFT JOIN "inventory" ON "t13"."item" = "inventory"."item" AND "t13"."warehouse" = "inventory"."warehouse") AS "t14"
                                                            INNER JOIN (SELECT CASE WHEN "t17"."order_number" IS NULL THEN 'n' ELSE 'v' || CAST("t17"."order_number" AS VARCHAR) END AS "_ttrp_g_n9_0", CASE WHEN "t17"."line_no" IS NULL THEN 'n' ELSE 'v' || CAST("t17"."line_no" AS VARCHAR) END AS "_ttrp_g_n9_1", MAX("inventory0"."as_of_date") AS "_ttrp_latest_n9"
                                                                FROM (SELECT "t16"."order_number", "t16"."customer", "t16"."channel", "t16"."fulfilling_warehouse", "t16"."value", "t16"."placed_date", "t16"."state", "sales_line2"."line_no", "sales_line2"."item", "sales_line2"."quantity", "sales_line2"."unit_price", "sales_line2"."ext_sales_price", "sales_line2"."warehouse", "sales_line2"."sold_date", "sales_line2"."customer" AS "customer0", "sales_line2"."channel" AS "channel0"
                                                                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                                FROM "order"
                                                                                WHERE "state" IN ('held', 'placed')) AS "t16"
                                                                            INNER JOIN "sales_line" AS "sales_line2" ON "t16"."order_number" = "sales_line2"."order_number") AS "t17"
                                                                    LEFT JOIN "inventory" AS "inventory0" ON "t17"."item" = "inventory0"."item" AND "t17"."warehouse" = "inventory0"."warehouse"
                                                                GROUP BY CASE WHEN "t17"."order_number" IS NULL THEN 'n' ELSE 'v' || CAST("t17"."order_number" AS VARCHAR) END, CASE WHEN "t17"."line_no" IS NULL THEN 'n' ELSE 'v' || CAST("t17"."line_no" AS VARCHAR) END) AS "t19" ON "t14"."_ttrp_g_n9_0" = "t19"."_ttrp_g_n9_0" AND "t14"."_ttrp_g_n9_1" = "t19"."_ttrp_g_n9_1" AND "t14"."as_of_date" = "t19"."_ttrp_latest_n9") AS "t20"
                                                    LEFT JOIN (SELECT *
                                                        FROM "warehouse_outage"
                                                        WHERE "from_date" <= :as_of AND "to_date" >= :as_of) AS "t21" ON "t20"."warehouse" = "t21"."warehouse") AS "t22"
                                        WHERE "t22"."outage" OR "t22"."on_hand" < "t22"."quantity"
                                        GROUP BY "order_number") AS "t25" ON "t10"."order_number" = "t25"."order_number") AS "t26"
                            LEFT JOIN (SELECT "order_number0" AS "order_number", COUNT("line_no0") AS "n_price"
                                FROM (SELECT "t29"."order_number", "t29"."line_no", "t29"."item", "t29"."unit_price", "t29"."customer", "t29"."channel", "t29"."placed_date", "t33"."order_number" AS "order_number0", "t33"."line_no" AS "line_no0", "t33"."price"
                                        FROM (SELECT "sales_line3"."order_number", "sales_line3"."line_no", "sales_line3"."item", "sales_line3"."unit_price", "t28"."customer", "t28"."channel", "t28"."placed_date"
                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                        FROM "order"
                                                        WHERE "state" IN ('held', 'placed')) AS "t28"
                                                    INNER JOIN "sales_line" AS "sales_line3" ON "t28"."order_number" = "sales_line3"."order_number") AS "t29"
                                            INNER JOIN (SELECT "t32"."order_number", "t32"."line_no", COALESCE("customer_price0"."price", "price_list0"."price") AS "price"
                                                FROM (SELECT "sales_line4"."order_number", "sales_line4"."line_no", "sales_line4"."item", "sales_line4"."unit_price", "t31"."customer", "t31"."channel", "t31"."placed_date"
                                                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                FROM "order"
                                                                WHERE "state" IN ('held', 'placed')) AS "t31"
                                                            INNER JOIN "sales_line" AS "sales_line4" ON "t31"."order_number" = "sales_line4"."order_number") AS "t32"
                                                    LEFT JOIN "customer_price" AS "customer_price0" ON "t32"."item" = "customer_price0"."item" AND "t32"."customer" = "customer_price0"."customer" AND "t32"."placed_date" >= "customer_price0"."valid_from" AND ("customer_price0"."valid_to" IS NULL OR "t32"."placed_date" <= "customer_price0"."valid_to")
                                                    LEFT JOIN "price_list" AS "price_list0" ON "t32"."item" = "price_list0"."item" AND "t32"."channel" = "price_list0"."channel" AND "t32"."placed_date" >= "price_list0"."valid_from" AND ("price_list0"."valid_to" IS NULL OR "t32"."placed_date" <= "price_list0"."valid_to")) AS "t33" ON "t29"."order_number" = "t33"."order_number" AND "t29"."line_no" = "t33"."line_no") AS "t34"
                                WHERE "t34"."price" IS NULL OR ABS("t34"."unit_price" - "t34"."price") > :tolerance
                                GROUP BY "order_number0") AS "t37" ON "t26"."order_number" = "t37"."order_number") AS "t38"
                    LEFT JOIN (SELECT "order_number", COUNT("invoice_id") AS "n_due"
                        FROM (SELECT "t40"."order_number", "t40"."customer", "t40"."channel", "t40"."fulfilling_warehouse", "t40"."value", "t40"."placed_date", "t40"."state", "invoice"."invoice_id", "invoice"."order_number" AS "order_number0", "invoice"."issued", "invoice"."due", "invoice"."amount", "invoice"."paid", "invoice"."status"
                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                        FROM "order"
                                        WHERE "state" IN ('held', 'placed')) AS "t40"
                                    INNER JOIN "invoice" ON "t40"."customer" = "invoice"."customer") AS "t41"
                        WHERE "t41"."status" = 'open' AND "t41"."due" < :as_of
                        GROUP BY "order_number") AS "t44" ON "t38"."order_number" = "t44"."order_number") AS "t45"
        WHERE "t45"."n_short" > 0 OR "t45"."n_price" > 0
        GROUP BY "order_number") AS "t48" ON "t8"."order_number" = "t48"."order_number"
